insert into study894_definition_vectors values
 ('valid-baseline',true,pg_temp.study894_definition()),
 ('valid-multibyte-below-boundary',true,jsonb_set(pg_temp.study894_definition(),'{goal}',to_jsonb(repeat(U&'\+01F600',2049)))),
 ('valid-codepoint-boundary',true,jsonb_set(pg_temp.study894_definition(),'{goal}',to_jsonb(repeat(U&'\+01F600',4096)))),
 ('missing-functional-unit-fields',false,jsonb_set(pg_temp.study894_definition(),'{functionalUnit}','{}')),
 ('unknown-functional-unit-field',false,jsonb_set(pg_temp.study894_definition(),'{functionalUnit,extra}','true')),
 ('unknown-definition-field',false,pg_temp.study894_definition()||'{"unknown":true}'),
 ('missing-goal',false,pg_temp.study894_definition()-'goal'),
 ('numeric-goal',false,jsonb_set(pg_temp.study894_definition(),'{goal}','1')),
 ('blank-goal',false,jsonb_set(pg_temp.study894_definition(),'{goal}','" "')),
 ('unicode-blank-goal',false,jsonb_set(pg_temp.study894_definition(),'{goal}',to_jsonb(U&'\00A0\FEFF'::text))),
 ('control-in-goal',false,jsonb_set(pg_temp.study894_definition(),'{goal}',to_jsonb('text'||chr(1)))),
 ('overlong-goal',false,jsonb_set(pg_temp.study894_definition(),'{goal}',to_jsonb(repeat('x',4097)))),
 ('overlong-codepoint-goal',false,jsonb_set(pg_temp.study894_definition(),'{goal}',to_jsonb(repeat(U&'\+01F600',4097)))),
 ('numeric-unit-amount',false,jsonb_set(pg_temp.study894_definition(),'{functionalUnit,amount}','1')),
 ('zero-unit-amount',false,jsonb_set(pg_temp.study894_definition(),'{functionalUnit,amount}','"0"')),
 ('negative-unit-amount',false,jsonb_set(pg_temp.study894_definition(),'{functionalUnit,amount}','"-1"')),
 ('exponent-unit-amount',false,jsonb_set(pg_temp.study894_definition(),'{functionalUnit,amount}','"1e3"')),
 ('null-unit-amount',false,jsonb_set(pg_temp.study894_definition(),'{functionalUnit,amount}','null')),
 ('blank-unit',false,jsonb_set(pg_temp.study894_definition(),'{functionalUnit,unit}','" "')),
 ('invalid-reference-id',false,jsonb_set(pg_temp.study894_definition(),'{functionalUnit,referenceFlowId}','"bad id"')),
 ('numeric-reference-id',false,jsonb_set(pg_temp.study894_definition(),'{functionalUnit,referenceFlowId}','1')),
 ('empty-methods',false,jsonb_set(pg_temp.study894_definition(),'{methodRefs}','[]')),
 ('unknown-method-field',false,jsonb_set(pg_temp.study894_definition(),'{methodRefs,0,extra}','true')),
 ('missing-method-version',false,jsonb_set(pg_temp.study894_definition(),'{methodRefs}',jsonb_build_array((pg_temp.study894_definition()->'methodRefs'->0)-'version'))),
 ('wrong-method-kind',false,jsonb_set(pg_temp.study894_definition(),'{methodRefs,0,datasetType}','"process"')),
 ('duplicate-method-id',false,jsonb_set(pg_temp.study894_definition(),'{methodRefs}',(pg_temp.study894_definition()->'methodRefs')||(pg_temp.study894_definition()->'methodRefs'))),
 ('assumptions-not-array',false,jsonb_set(pg_temp.study894_definition(),'{assumptions}','{}')),
 ('missing-assumption-fields',false,jsonb_set(pg_temp.study894_definition(),'{assumptions}','[{}]')),
 ('unknown-assumption-field',false,jsonb_set(pg_temp.study894_definition(),'{assumptions}','[{"id":"a","statement":"text","evidenceRef":"e","extra":true}]')),
 ('numeric-assumption-statement',false,jsonb_set(pg_temp.study894_definition(),'{assumptions}','[{"id":"a","statement":1,"evidenceRef":"e"}]')),
 ('missing-assumption-evidence',false,jsonb_set(pg_temp.study894_definition(),'{assumptions}','[{"id":"a","statement":"text"}]')),
 ('too-many-assumptions',false,jsonb_set(pg_temp.study894_definition(),'{assumptions}',(select jsonb_agg(jsonb_build_object('id','a'||i,'statement','text','evidenceRef','e')) from generate_series(1,129)i)));
